hudson.tasks.Shell.command:
set -Eeuo pipefail TOKEN=$(cat /opt/jenkins/github_token_common) REPO="https://wangzi-prince:${TOKEN}@github.com/wangzi-prince/CYT-Common.git" PROXY=http://172.18.0.6:7890 WORK=/tmp/cyt-common-build-$$ cleanup() { rm -rf "$WORK"; echo "==> 已清理临时工作区 $WORK"; } trap cleanup EXIT
clone_it() { local proxy="$1" if [[ -n "$proxy" ]]; then env GIT_TERMINAL_PROMPT=0 GIT_HTTP_LOW_SPEED_LIMIT=1000 GIT_HTTP_LOW_SPEED_TIME=20 \ HTTP_PROXY="$proxy" HTTPS_PROXY="$proxy" \ git clone --depth 1 --branch "$BRANCH" "$REPO" "$WORK" else env GIT_TERMINAL_PROMPT=0 GIT_HTTP_LOW_SPEED_LIMIT=1000 GIT_HTTP_LOW_SPEED_TIME=20 \ git clone --depth 1 --branch "$BRANCH" "$REPO" "$WORK" fi }
echo "==> 分支: $BRANCH 只构建不重启: $SKIP_DEPLOY" if ! clone_it ""; then echo "==> 直连 GitHub 失败，改走代理 $PROXY 重试" rm -rf "$WORK" clone_it "$PROXY" fi cd "$WORK" echo "==> 当前提交: $(git log --oneline -1)" SKIP_DEPLOY="$SKIP_DEPLOY" bash deploy/test-server/ci-build.sh
